output_text:
[
  {
    "id": "take_cart_at_entrance",
    "text": "A shopper is obliged to take the available entrance cart before continuing with the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)"
      },
      "events": {
        "took_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_bay",
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "took_entrance_cart"
    }
  },
  {
    "id": "do_not_pass_cart_bay_without_cart",
    "text": "A shopper is prohibited from walking east past the entrance cart bay while the entrance cart is still there.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "has_not_taken_cart": {
          "not": "hasCart"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at_entrance_cart_bay",
          "entrance_cart_available",
          "has_not_taken_cart",
          "E"
        ]
      }
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have the shopping cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_required_items",
    "text": "A shopper is prohibited from carrying groceries by hand instead of using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "picked_item_without_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "picked_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_corral",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return point at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "returned_cart_to_corral": {
          "pre": {
            "and": [
              "at_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "returned_cart_to_corral"
    }
  },
  {
    "id": "leave_cart_before_exit",
    "text": "A shopper is prohibited from exiting the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "at_store_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_store_exit",
              "hasCart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "only_leave_cart_at_return_point",
    "text": "A shopper is prohibited from putting the cart down anywhere except the cart-return point at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "away_from_cart_return": {
          "not": "at_cart_return"
        }
      },
      "events": {
        "abandoned_cart_away_from_return": {
          "pre": {
            "and": [
              "away_from_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandoned_cart_away_from_return"
    }
  },
  {
    "id": "cart_free_exit_corridor",
    "text": "Carts are prohibited in the customer-only exit corridor after checkout.",
    "abstraction": {
      "state_properties": {
        "east_exit_corridor": {
          "or": [
            "at(2,2)",
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "east_exit_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_corridor"
    }
  }
]
